import{_ as a,o,c as r,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Пассивные аванпосты: работники, склад и восстановление","description":"","frontmatter":{"pageId":"players/passive-outposts","contentRevision":7},"headers":[],"relativePath":"ru/players/passive-outposts.md","filePath":"ru/players/passive-outposts.md"}'),i={name:"ru/players/passive-outposts.md"};function s(l,e,c,p,n,d){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="пассивные-аванпосты-работники-склад-и-восстановление" tabindex="-1">Пассивные аванпосты: работники, склад и восстановление <a class="header-anchor" href="#пассивные-аванпосты-работники-склад-и-восстановление" aria-label="Permalink to &quot;Пассивные аванпосты: работники, склад и восстановление&quot;">​</a></h1><h2 id="usage" tabindex="-1">Доступность и подготовка <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Доступность и подготовка {#usage}&quot;">​</a></h2><p>В этой ветке находится реализация аванпостов; <strong>Product остаётся Pending и не объявляет capability</strong>. Настройка сервера, администратор или подтверждённый манифест не открывают этот gate. Приёмка G1–G7 на двух клиентах и единственный итоговый обзор Astra проведены. Исправления семи замечаний подтверждены целевыми проверками и четырьмя затронутыми игровыми сценариями. Ниже описано поведение изолированного стенда.</p><p>Аванпост — серверное рабочее место без симулируемой карты. Приведите фактически прибывший караван с подходящими свободными взрослыми baseline human колонистами на доступный тайл полного манифеста мира, подтверждённого администратором. Игра и core сохраняют точную сериализованную личность работников, включая поддерживаемые genes и DLC-ссылки. Сервер не генерирует местность. Игроки на одной планете могут выбирать разные сценарии колонии, рассказчиков и сложность. Для совместимости манифеста проверяются общие параметры мира, фактическая сборка игры, активные DLC и игровые определения.</p><p>Колония может владеть одним аванпостом с 1–4 работниками. Основание резервирует 500 silver из серверного кошелька и списывает их один раз на commit. Склад вмещает 1000 отдельных единиц ресурсов. Поддерживаются только WoodLog и Steel: дереву нужны природные деревья и подходящая biome, стали — доступная подходящая земля. Поселения, NPC-объекты, аванпосты и резервации исключают тайл. Игра проверяет фактические локальные quest/mod world objects перед Prepare и повторно перед удалением работников. Исключения допускаются для самого выбранного каравана и собственного Active-маркера при Assign. Влияние гильдии не даёт территориальных прав.</p><h2 id="production" tabindex="-1">Добыча и управление <a class="header-anchor" href="#production" aria-label="Permalink to &quot;Добыча и управление {#production}&quot;">​</a></h2><p>Добыча учитывает прошедшее реальное время, включая офлайн. На серверном хранении работникам не нужны еда и содержание; они не стареют, не болеют и не развивают навыки. Навыки и показатели здоровья/способностей фиксируются при уходе. Часовая выработка работника равна 20 дерева или 10 стали, умноженным на <code>(0.5 + 0.05 × clampedSkill) × H</code>; H — минимум сознания, манипуляции и передвижения в пределах 0..1, строго положительный. Сервер хранит точную дробь без накопления округлений float.</p><p>Полный склад останавливает добычу, обнуляет дробный остаток и не копит отложенную выработку. Получение склада возвращает целую часть и сохраняет дробь. Отзыв части работников сохраняет склад и дробь. Отзыв последнего работника или закрытие возвращает всех оставшихся работников и склад с предупреждением о потере дроби. Переключение профиля требует пустого склада и явного подтверждения потери дроби. Закрытие не возвращает плату за основание.</p><h2 id="recovery" tabindex="-1">Доставка и неопределённые ответы <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Доставка и неопределённые ответы {#recovery}&quot;">​</a></h2><p>Получатель ожидающей защищённой посылки уже требует совместимого клиента, даже пока custody остаётся у отправителя. Это проверяется при входе, сохранении и получении физических blobs. Неподдерживаемый клиент получает OutpostClientRequired до выдачи содержимого.</p><p>Доставка в собственный mailbox ручная, бесплатная и мгновенная на сервере; физическое получение происходит дома, а не в караване. Точные UUID registry, custody lineage, доказательства принятых сохранений и receipts защищают от повторного spawn или credit. Уже принятая квитанция разрешает только подтверждение известного исхода. Если возвращённого работника продали колонии с обычными сохранениями, он остаётся в эскроу, пока сервер не примет первое защищённое сохранение покупателя с квитанцией о выдаче. Серверный UUID работника сохраняется. Если проверка совместимости отказала до размещения, игра ставится на паузу и блокирует сохранения. Посылка остаётся на сервере до устранения причины отказа.</p><p>Commit или Cancel с промежуточным Prepared, RecoveryRequired либо cancellation fence сохраняет исходный журнал до допустимого окончательного результата. Проверяются scope, ID операции и digest ответа. Выход в меню или смена сессии освобождает временное состояние Busy, сохраняя долговечный outbox. Освобождение Busy привязано к идентификатору запуска.</p><p>При неопределённом ответе сохраняйте запись outbox, локальный capture и сохранения. Читайте исходный результат и повторяйте именно исходный запрос через восстановление. Unknown, отсутствие флага, тайм-аут или старое сохранение не доказывают, что имущество не было изъято. Не создавайте замену работнику, не отправляйте подарок заново и не сбрасывайте колонию ради обхода RecoveryRequired.</p><p>После аварийного закрытия и нового запуска игры неопределённая операция может остановить вход с RecoveryRequired. Исходный запрос и локальные сохранения сохраняются для проверки; такой отказ не подтверждает отмену, возврат работников или выдачу посылки. Утраченная непрерывность игровой ветки не восстанавливается загрузкой старого сохранения.</p><p>Подтверждённый отказ на первый запрос отправки работников оставляет их в караване и удаляет только отклонённый запрос, если причина — недоступный слот или цель назначения, занятый или неподходящий тайл, неподтверждённый или изменившийся манифест, неподходящий работник, недостаток средств на основание, долг, заморозка торговли либо угроза, запрещающая основание. То же правило действует при подтверждённом отказе на первую команду владельца, если изменились аванпост или выбор работников для отзыва, либо профиль, запас или подтверждение потери дроби не допускают переключение. Прежний неопределённый запрос, тайм-аут, несовпадение идентичности или повреждённые доказательства требуют восстановления.</p><p>Если после неопределённого Prepare продолжается та же непрерывная игровая ветка и работники не изымались, обычная отмена сначала читает исходную операцию и запрашивает свежий cancellation fence. Первый запрос сохраняет исходный PreRemoval proof в durable журнале, связанном с исходной операцией. Только при получении первого fence этот proof может быть историческим принятым сохранением: reconnect уже мог продвинуть canonical save. Это ещё не доказывает отсутствие изъятия. Затем игра сохраняет фактическое текущее состояние с NoRemoval receipt именно нового fence и ждёт принятия свежего текущего proof сервером; только после этого отмена завершается. Сам по себе RecoveryRequired может лишь удерживать исходную операцию и не разрешает создать receipt от другого перехода.</p><p>Отмена после изъятия может выбрать только существующий доказанный однопакетный возврат; требование текущего принятого proof для ReturnAfterRemoval не меняется. Положительные committed/accepted исходы имеют приоритет в гонке. Fences обычной передачи, рейда и live-сессии сохраняются после приёмки, очистки, архива, rollback и restore.</p><h2 id="limits" tabindex="-1">Ограничения и lifecycle <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и lifecycle {#limits}&quot;">​</a></h2><p>Отключение новых аванпостов не отключает защиту существующей истории. Несовместимый клиент не может перезаписать защищённую metadata или получить неподдерживаемый payload; несвязанные legacy-колонии сохраняют прежнее поведение. Отсутствующая или повреждённая authority/evidence закрывает защищённые операции.</p><p>Архив приостанавливает добычу. Сброс требует закрытого аванпоста, принятых физических receipts и разрешённой custody. Rollback сохраняет исходные байты доказательств и продвигает только текущую разрешённую view; он не откатывает добытый склад и не разрешает повторную выдачу. Bulk restore выполняется отдельно при остановленном сервере и требует нового принятого capture после разрешённой загрузки canonical save. Администратор может проверить или выбрать доказанный исход, но не отметить payload принятым, очистить fence или выдумать отсутствие источника.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./../admins/passive-outposts">Готовность сервера и точные команды администратора</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li><li><a href="./world">Карта мира</a></li></ul>',22)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
